select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.name = 'Zed Agent' order by e.first_seen_at desc limit 1), 'fr', 'short_description',
  'Éditeur de code open source et rapide, avec un agent IA intégré qui modifie plusieurs fichiers, fonctionne avec les modèles de Zed ou vos propres clés, et accueille des agents externes.',
  'Fast open-source code editor with a built-in AI agent that edits across files, runs on Zed-hosted models or your own keys, and works with external agents.');
select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.name = 'Kilo Code' order by e.first_seen_at desc limit 1), 'fr', 'short_description',
  'Agent de code IA open source pour VS Code, JetBrains et la ligne de commande, qui planifie, écrit et corrige le code avec des centaines de modèles, facturés au prix des fournisseurs.',
  'Open-source AI coding agent for VS Code, JetBrains and the command line that plans, writes and fixes code with hundreds of models, billed at provider rates.');
select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.name = 'Greptile' order by e.first_seen_at desc limit 1), 'fr', 'short_description',
  'Relecteur de code IA qui lit toute votre base de code et commente les pull requests GitHub en signalant bugs, risques et corrections proposées.',
  'AI code reviewer that reads your whole codebase and comments on GitHub pull requests with bugs, risks and suggested fixes.');
select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.name = 'Graphite (AI code review)' order by e.first_seen_at desc limit 1), 'fr', 'short_description',
  'Plateforme de revue de code avec pull requests empilées et un relecteur IA qui commente chaque modification, pour les équipes qui livrent vite sur GitHub.',
  'Code review platform with stacked pull requests and an AI reviewer that comments on every change, for teams that ship fast on GitHub.');
select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.name = 'Bito AI Code Review Agent' order by e.first_seen_at desc limit 1), 'fr', 'short_description',
  'Agent IA de revue de code pour GitHub, GitLab et Bitbucket, qui laisse des remarques ligne par ligne, des corrections proposées et des résumés de pull request.',
  'AI code review agent for GitHub, GitLab and Bitbucket that posts line-by-line feedback, suggested fixes and pull request summaries.');
select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.name = 'Rork' order by e.first_seen_at desc limit 1), 'fr', 'short_description',
