select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.name = 'Goodcall' order by e.first_seen_at desc limit 1), 'fr', 'short_description',
  'Agent téléphonique IA pour les petites entreprises : il répond à chaque appel, prend les rendez-vous, recueille les contacts et envoie des SMS de suivi, facturé par appelant unique.',
  'AI phone agent for small businesses that answers every call, books appointments, captures leads and texts follow-ups, billed per unique caller.');
select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.name = 'Dialpad AI Agents' order by e.first_seen_at desc limit 1), 'fr', 'short_description',
  'Agents IA pour les conversations clients au téléphone et en ligne : ils consultent les commandes, prennent les rendez-vous, orientent et passent la main aux conseillers dans le centre de contact Dialpad.',
  'AI agents for voice and digital customer conversations that look up orders, schedule, route and hand over to human agents inside Dialpad''s contact center.');
select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.name = 'Momentum' order by e.first_seen_at desc limit 1), 'fr', 'short_description',
