  'AI teammate for support teams that answers tickets and chats in your help desk, drafts replies and handles routine work, trained on your past tickets and docs.');
select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.name = 'invideo AI' order by e.first_seen_at desc limit 1), 'fr', 'short_description',
  'Créateur vidéo IA : décrivez une vidéo et son agent écrit le script, choisit les images, génère les scènes et la voix off, puis vous laisse retoucher par consigne.',
  'AI video creator: describe a video and its agent writes the script, picks footage, generates scenes and voice-over, then lets you edit by prompt.');
select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.name = 'Fini' order by e.first_seen_at desc limit 1), 'fr', 'short_description',
  'Agent IA de support client qui règle les tickets de bout en bout dans votre outil d''assistance et ne facture que les tickets résolus, sans frais par siège.',
  'AI customer support agent that resolves tickets end to end in your help desk and charges only for resolved tickets, with no seat fees.');

select refresh_rankings();

select e.name, 'https://electraindex.com/agents/' || e.slug as page,
       (select count(*) from entities x where x.type = 'agent' and x.is_published) as agents_total
  from entities e where e.type = 'agent' and e.name in ('Zed Agent', 'Kilo Code', 'Greptile', 'Graphite (AI code review)', 'Bito AI Code Review Agent', 'Rork', 'Goodcall', 'Dialpad AI Agents', 'Momentum', 'eesel AI', 'invideo AI', 'Fini') order by e.name;
